"use strict";(self.webpackChunkcursos=self.webpackChunkcursos||[]).push([["4661"],{1537(a){a.exports=JSON.parse('{"version":{"pluginId":"programacion","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"programacionSidebar":[{"type":"category","label":"UT1 - Elementos b\xe1sicos","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/cursosdesarrollo/programacion-java/ut1-introduccion/elementos-basicos","label":"1. Elementos b\xe1sicos","docId":"ut1-introduccion/elementos-basicos","unlisted":false}]},{"type":"category","label":"UT2 - Estructuras de control","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/cursosdesarrollo/programacion-java/ut2-estructuras-control/estructuras-seleccion","label":"1. Estructuras de selecci\xf3n","docId":"ut2-estructuras-control/estructuras-seleccion","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut2-estructuras-control/estructuras-repeticion","label":"2. Estructuras de repetici\xf3n","docId":"ut2-estructuras-control/estructuras-repeticion","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut2-estructuras-control/ejercicio-rombo","label":"Ejercicio guiado \u2014 Rombo","docId":"ut2-estructuras-control/ejercicio-rombo","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut2-estructuras-control/funciones","label":"3. Funciones","docId":"ut2-estructuras-control/funciones","unlisted":false}]},{"type":"category","label":"UT3 - Estructuras de datos est\xe1ticas","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-introduccion","label":"1. Introducci\xf3n a los arrays","docId":"ut3-estructuras-datos/arrays-introduccion","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-memoria","label":"2. Los arrays en memoria","docId":"ut3-estructuras-datos/arrays-memoria","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-recorrer-algoritmos","label":"3. Recorrer y algoritmos b\xe1sicos","docId":"ut3-estructuras-datos/arrays-recorrer-algoritmos","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-clase-arrays-copia","label":"4. Clase Arrays y copia","docId":"ut3-estructuras-datos/arrays-clase-arrays-copia","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-insertar-eliminar","label":"5. Insertar y eliminar","docId":"ut3-estructuras-datos/arrays-insertar-eliminar","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-ordenacion","label":"6. Ordenar un array","docId":"ut3-estructuras-datos/arrays-ordenacion","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/matrices","label":"7. Matrices","docId":"ut3-estructuras-datos/matrices","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/matrices-algoritmos","label":"8. Algoritmos con matrices","docId":"ut3-estructuras-datos/matrices-algoritmos","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-funciones","label":"9. Arrays y funciones","docId":"ut3-estructuras-datos/arrays-funciones","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/ejercicio-buscaminas","label":"Ejercicio guiado \u2014 Buscaminas","docId":"ut3-estructuras-datos/ejercicio-buscaminas","unlisted":false},{"type":"link","href":"/cursosdesarrollo/programacion-java/ut3-estructuras-datos/arrays-resumen","label":"11. Resumen y errores frecuentes","docId":"ut3-estructuras-datos/arrays-resumen","unlisted":false}]}]},"docs":{"ut1-introduccion/elementos-basicos":{"id":"ut1-introduccion/elementos-basicos","title":"1. Elementos b\xe1sicos de la programaci\xf3n","description":"Los elementos b\xe1sicos de un programa en Java: la estructura del programa principal, las palabras reservadas, los comentarios, las variables, las constantes, los operadores y las primeras clases de la API que utilizaremos.","sidebar":"programacionSidebar"},"ut2-estructuras-control/ejercicio-rombo":{"id":"ut2-estructuras-control/ejercicio-rombo","title":"Ejercicio guiado \u2014 Dibuja un rombo con bucles anidados","description":"En esta p\xe1gina vamos a resolver, paso a paso, un ejercicio de bucles anidados algo m\xe1s complejo que los que hemos visto hasta ahora.","sidebar":"programacionSidebar"},"ut2-estructuras-control/estructuras-repeticion":{"id":"ut2-estructuras-control/estructuras-repeticion","title":"2. Estructuras de repetici\xf3n","description":"Las estructuras de repetici\xf3n o iterativas permiten repetir una misma secuencia de instrucciones varias veces, mientras se cumpla una cierta condici\xf3n.","sidebar":"programacionSidebar"},"ut2-estructuras-control/estructuras-seleccion":{"id":"ut2-estructuras-control/estructuras-seleccion","title":"1. Estructuras de selecci\xf3n","description":"Las estructuras de selecci\xf3n permiten tomar decisiones sobre qu\xe9 conjunto de instrucciones ejecutar en un punto del programa. O sea, seleccionar qu\xe9 c\xf3digo se ejecuta en un momento determinado entre caminos alternativos.","sidebar":"programacionSidebar"},"ut2-estructuras-control/funciones":{"id":"ut2-estructuras-control/funciones","title":"3. Funciones","description":"Una funci\xf3n (en Java, t\xe9cnicamente un m\xe9todo) es un bloque de c\xf3digo independiente al que le damos un nombre, para poder ejecutarlo desde distintos puntos del programa sin tener que repetir su c\xf3digo cada vez. Nos permiten dividir un programa grande en piezas m\xe1s peque\xf1as, reutilizables y f\xe1ciles de probar.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-clase-arrays-copia":{"id":"ut3-estructuras-datos/arrays-clase-arrays-copia","title":"4. La clase Arrays y copiar arrays","description":"La API de Java incluye herramientas que facilitan el trabajo con arrays. Del mismo modo que usamos la clase Math o Scanner, podemos usar la clase Arrays, que contiene m\xe9todos est\xe1ticos para operar con ellos.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-funciones":{"id":"ut3-estructuras-datos/arrays-funciones","title":"9. Arrays y funciones","description":"Los programas con arrays crecen r\xe1pido: leer datos, mostrarlos, sumarlos, buscar... Si todo est\xe1 en el main, el c\xf3digo se vuelve largo y dif\xedcil de leer. Lo natural es dividirlo en funciones, cada una con una \xfanica tarea. En esta p\xe1gina vemos c\xf3mo pasar arrays a una funci\xf3n, c\xf3mo devolverlos y qu\xe9 ocurre con los cambios que hagamos dentro.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-insertar-eliminar":{"id":"ut3-estructuras-datos/arrays-insertar-eliminar","title":"5. Insertar y eliminar elementos","description":"Un array tiene tama\xf1o fijo: una vez creado no puede crecer ni encogerse. Pero en muchos programas necesitamos a\xf1adir o quitar datos (una lista de la compra, los jugadores de una partida...). En esta p\xe1gina vemos c\xf3mo simular esas operaciones con arrays.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-introduccion":{"id":"ut3-estructuras-datos/arrays-introduccion","title":"1. Introducci\xf3n a los arrays","description":"Hasta ahora, cada variable que hemos usado guardaba un \xfanico valor. Pero muchos problemas necesitan manejar muchos datos a la vez: las notas de una clase, las temperaturas de un mes, los nombres de los jugadores de una partida... En esta unidad vemos los arrays (tambi\xe9n llamados vectores o tablas) y las matrices, que nos permiten guardar un conjunto de datos bajo un mismo nombre.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-memoria":{"id":"ut3-estructuras-datos/arrays-memoria","title":"2. Los arrays en memoria","description":"Con los tipos primitivos (int, double, boolean...) una variable contiene directamente su valor. Con los arrays no ocurre lo mismo, y entender la diferencia es imprescindible para no cometer errores muy dif\xedciles de detectar.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-ordenacion":{"id":"ut3-estructuras-datos/arrays-ordenacion","title":"6. Ordenar un array","description":"Ordenar datos es una de las tareas m\xe1s habituales en programaci\xf3n. Java ya incluye Arrays.sort, pero entender c\xf3mo se ordena un array a mano es un ejercicio excelente para practicar bucles anidados y el manejo de \xedndices. En esta p\xe1gina vemos dos algoritmos sencillos: el de burbuja y el de selecci\xf3n.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-recorrer-algoritmos":{"id":"ut3-estructuras-datos/arrays-recorrer-algoritmos","title":"3. Recorrer arrays y algoritmos b\xe1sicos","description":"La gran ventaja de los arrays es que podemos recorrerlos con un bucle y aplicar la misma operaci\xf3n a todos sus elementos. En esta p\xe1gina vemos las dos formas de recorrerlos y los algoritmos m\xe1s habituales: sumar, calcular la media, buscar el m\xe1ximo, contar, buscar un valor e invertir.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/arrays-resumen":{"id":"ut3-estructuras-datos/arrays-resumen","title":"11. Resumen y errores frecuentes","description":"Una p\xe1gina de consulta r\xe1pida para repasar la unidad: la sintaxis esencial, los errores que m\xe1s se repiten y unas preguntas para comprobar si lo has entendido.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/ejercicio-buscaminas":{"id":"ut3-estructuras-datos/ejercicio-buscaminas","title":"Ejercicio guiado \u2014 Buscaminas simplificado","description":"En esta p\xe1gina vamos a resolver, paso a paso, un ejercicio con matrices y bucles anidados de dificultad media-alta el objetivo es que la construyas t\xfa, en tu editor, fase a fase.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/matrices":{"id":"ut3-estructuras-datos/matrices","title":"7. Matrices (arrays bidimensionales)","description":"Hasta ahora todos los arrays ten\xedan una sola dimensi\xf3n las notas de varios alumnos en varias asignaturas, un tablero de ajedrez, los p\xedxeles de una imagen... Para eso existen los arrays de m\xe1s de una dimensi\xf3n, y el caso m\xe1s habitual es el de dos dimensiones: la matriz.","sidebar":"programacionSidebar"},"ut3-estructuras-datos/matrices-algoritmos":{"id":"ut3-estructuras-datos/matrices-algoritmos","title":"8. Algoritmos con matrices","description":"Con las matrices aplicamos las mismas ideas que con los arrays de una dimensi\xf3n (acumuladores, contadores, m\xe1ximos...), pero recorriendo con dos bucles anidados. En esta p\xe1gina vemos los algoritmos m\xe1s habituales. En todos los ejemplos partimos de esta matriz:","sidebar":"programacionSidebar"}}}}')}}]);